      SUBROUTINE MRR2VCC     MULTIPLIES RSH AND R2V AND STORES RESULT IN R2VCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R2VS.CIN'      INCLUDE 'R2VT.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RC3.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'T2VT.CIN'      INCLUDE 'TC2.CIN'      INCLUDE 'TC3.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'U2VS.CIN'      INCLUDE 'U2VT.CIN'      INCLUDE 'UC2.CIN'      INCLUDE 'UC3.CIN'      INCLUDE 'US.CIN'CC-----------------------------------------------------------------      N = NV2      DO 10 JK = 1, 36      R2VTL(JK) = R2VL(JK,N)   10 CONTINUE      IF (NORD2 .GE. 2) THEN        DO 20 JKL = 1, 105        T2VTL(JKL) = T2VL(JKL,N)   20   CONTINUE      ENDIF      IF (NORD2 .GE. 3) THEN        DO 30 JKL = 1, 280        U2VTL(JKL) = U2VL(JKL,N)   30   CONTINUE      ENDIFC      IF (NORD2 .EQ. 1) THEN        CALL CAB(RS,RSH,R2VT)      ELSE IF (NORD2 .EQ. 2) THEN        CALL CABD2(RS,TS,RSH,TSH,RC2,R2VT,T2VT)      ELSE IF (NORD2 .GE. 3) THEN        CALL CABD3(RS,TS,US,RSH,TSH,USH,RC2,TC2,     >             R2VT,T2VT,U2VT)      ENDIFC      DO 50 JK = 1, 36   50 R2VSL(JK,N) = RSL(JK)      IF (NORD2 .GE. 2) THEN        DO 60 IJK = 1, 105   60   T2VL(IJK,N) = TSL(IJK)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 70 IJKL = 1, 280   70   U2VL(IJKL,N) = USL(IJKL)      ENDIF      RETURN      END